using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckStorageCases()
    {
        Check("Storage inventories are independent detached finite map records",()=>{
            WorldMap map=new WorldMap(12,9);StorageBoxDocument box=new StorageBoxDocument{x=4,y=3,capacity=30,items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=6}}};map.SetStorageBox(box);box.items[0].quantity=99;map.SetStorageBox(new StorageBoxDocument{x=8,y=3,capacity=30,items=new ItemStackDocument[0]});Require(StorageRules.Count(map.StorageBoxAt(4,3),InventoryItem.Food)==6 && StorageRules.Count(map.StorageBoxAt(8,3),InventoryItem.Food)==0 && map.ShelfAt(4,3)==null && !map.CanWalk(4,3),"Boxes alias inventories, masquerade as shelves or fail collision.");MapDocument saved=map.Capture();Require(saved.schemaVersion==8 && saved.storageBoxes.Length==2,"Box map did not declare its new schema.");string bytes=Documents.Encode(saved);WorldMap copy=Documents.ParseMap(bytes);Require(Documents.Encode(copy.Capture())==bytes,"Box inventories changed in map roundtrip.");saved.storageBoxes[0].items[0].quantity=1;StorageBoxDocument detached=copy.StorageBoxAt(4,3);detached.items[0].quantity=2;Require(StorageRules.Count(copy.StorageBoxAt(4,3),InventoryItem.Food)==6 && StorageRules.Count(map.StorageBoxAt(4,3),InventoryItem.Food)==6,"Captured or returned inventory mutated a live box.");
        });
        Check("Storage placement works outside rooms and rejects furniture bodies and reservations",()=>{
            World world=EncounterScenarios.StorageSupplyTest();string before=State(world);Require(!world.TryPlaceStorageBox(3,3) && !world.TryPlaceStorageBox(4,3) && !world.TryPlaceStorageBox(6,3) && !world.TryPlaceStorageBox(-1,3) && State(world)==before,"Rejected storage placement changed the world.");Require(world.TryPlaceStorageBox(9,7),"Generic box incorrectly required shelter floor.");int id;Require(!world.TrySpawn(Species.Human,9,7,out id) && !world.TryPlaceShelf(9,7,6),"Bodies or shelves overlap solid boxes.");WorldMap map=WorldMap.Restore(world.Capture().map);Reject(()=>map.SetShelf(9,7,2));Reject(()=>map.SetWeapon(9,7,MeleeWeapon.Bat));Require(map.StorageBoxAt(9,7).capacity==30,"Default box capacity is incorrect.");map.Set(9,7,Terrain.Wall);Require(map.StorageBoxAt(9,7)==null,"Replacing a box cell with a wall left hidden inventory.");
        });
        Check("Safe shelter occupants deposit real surplus in their storage box",()=>{
            World world=EncounterScenarios.StorageSupplyTest();world.Step();Require(world.ActorAt(0).carriedFood==1 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==2 && world.FoodSupplies().StorageMeals==2 && world.FoodSupplies().RemainingMeals==3,"Storage deposit failed reserve, conservation or overview totals.");World copy=Documents.ParseSave(State(world));Run(world,30);Run(copy,30);Require(State(world)==State(copy),"Storage stock diverged after save continuation.");
        });
        Check("Hungry humans withdraw finite box stock then eat on a later action",()=>{
            World world=EncounterScenarios.StorageSupplyTest(true);world.Step();Require(world.ActorAt(0).carriedFood==3 && world.ActorAt(0).hunger==80 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==3,"Box withdrawal created food or also ate in the pickup action.");World copy=Documents.ParseSave(State(world));Run(world,5);Run(copy,5);Require(world.ActorAt(0).hunger==30 && world.ActorAt(0).carriedFood==2 && world.FoodSupplies().RemainingMeals==5 && State(world)==State(copy),"Stored food did not satisfy hunger with conserved save continuation.");
        });
        Check("Storage capacity and recovery reserves bound actual deposits",()=>{
            SaveDocument saved=EncounterScenarios.StorageSupplyTest().Capture();saved.map.storageBoxes[0].capacity=1;World world=World.Restore(saved);world.Step();Require(world.ActorAt(0).carriedFood==2 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==1,"Box exceeded capacity or lost overflow food.");saved=EncounterScenarios.StorageSupplyTest().Capture();saved.actors[0].health=30;world=World.Restore(saved);world.Step();Require(world.ActorAt(0).carriedFood==2 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==1,"Injured donor lost its recovery reserve.");
        });
        Check("Multiple hungry humans cannot duplicate a shared box inventory",()=>{
            World world=EncounterScenarios.StorageSupplyTest(true);int id;Require(world.TrySpawn(Species.Human,4,4,out id),"Could not arrange competing box users.");SaveDocument saved=world.Capture();saved.map.storageBoxes[0].items[0].quantity=4;saved.actors[1].hunger=80;saved.actors[1].shelterId=27;saved.actors[1].shelterX=4;saved.actors[1].shelterY=4;saved.actors[1].shelterState=ShelterState.Inside;world=World.Restore(saved);Run(world,2);Require(world.ActorAt(0).carriedFood==3 && world.ActorAt(1).carriedFood==1 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==0 && world.FoodSupplies().RemainingMeals==4,"Concurrent withdrawals duplicated box stock.");
        });
        Check("Storage tasks route to an accessible face and resume exactly mid-trip",()=>{
            SaveDocument saved=EncounterScenarios.StorageSupplyTest().Capture();saved.actors[0].x=2;saved.actors[0].y=5;saved.actors[0].shelterX=2;saved.actors[0].shelterY=5;World world=World.Restore(saved);world.Step();Require(world.ActorAt(0).carriedFood==3 && world.ActorAt(0).energySpent>0,"Remote box deposit teleported supplies instead of walking.");World copy=Documents.ParseSave(State(world));Run(world,30);Run(copy,30);Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==2 && State(world)==State(copy),"Box trip failed to finish or diverged after saving.");
        });
        Check("Storage use respects infection freezes and observed danger",()=>{
            SaveDocument original=EncounterScenarios.StorageSupplyTest().Capture();foreach(int mode in new[]{0,1,2}){SaveDocument saved=Documents.ParseSave(Documents.Encode(original)).Capture();if(mode==0)saved.actors[0].turnAtTick=100;if(mode==1){saved.actors[0].reaction=HumanReaction.Freeze;saved.actors[0].freezeUntilTick=10;}World world=World.Restore(saved);if(mode==2){int id;Require(world.TrySpawn(Species.Zombie,2,3,out id),"Could not place visible threat.");}world.Step();Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==0,"Infected, frozen or threatened donor stocked a box (mode "+mode+").");}
        });
        Check("Malformed storage saves reject atomically and old rules remain unchanged",()=>{
            World world=EncounterScenarios.StorageSupplyTest(true);string before=State(world);Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.map.schemaVersion=7);bad(s=>s.map.storageBoxes[0].capacity=0);bad(s=>s.map.storageBoxes[0].items=null);bad(s=>s.map.storageBoxes[0].items[0].quantity=-1);bad(s=>s.map.storageBoxes[0].items[0].quantity=31);bad(s=>s.map.storageBoxes[0].items[0].item=(InventoryItem)9);bad(s=>s.map.storageBoxes=new[]{s.map.storageBoxes[0],s.map.storageBoxes[0]});bad(s=>s.map.storageBoxes[0].x=6);bad(s=>s.rulesVersion=EncounterRules.RiseAwarenessVersion);Require(State(world)==before,"Rejected storage save mutated the live world.");SaveDocument old=EncounterScenarios.PantryStorageTest().Capture();old.rulesVersion=EncounterRules.RiseAwarenessVersion;World legacy=World.Restore(old);Require(!legacy.StorageEnabled && !legacy.TryPlaceStorageBox(8,6),"Previous rules silently gained storage boxes.");World copy=World.Restore(legacy.Capture());Run(legacy,30);Run(copy,30);Require(State(legacy)==State(copy),"Previous shelf supply behavior stopped resuming exactly.");
        });
    }
}
